function(container, apiUrl, tables) {
  const docSelect = container.querySelector('[data-testid="document-select"]');
  const v1Select = container.querySelector('[data-testid="version1-select"]');
  const v2Select = container.querySelector('[data-testid="version2-select"]');
  const compareBtn = container.querySelector('[data-testid="compare-button"]');
  const backBtn = container.querySelector('[data-testid="back-button"]');
  const changeSummary = container.querySelector('#change-summary');
  const comparisonPanels = container.querySelector('#comparison-panels');
  const changeDetailsSection = container.querySelector('#change-details-section');
  const exportSection = container.querySelector('#export-section');
  const exportBtn = container.querySelector('[data-testid="export-comparison-button"]');

  const v1Panel = container.querySelector('#v1-panel');
  const v2Panel = container.querySelector('#v2-panel');
  const v1Info = container.querySelector('#v1-info');
  const v2Info = container.querySelector('#v2-info');
  const changeDetailsTbody = container.querySelector('#change-details-tbody');
  const addedCount = container.querySelector('#added-count');
  const deletedCount = container.querySelector('#deleted-count');
  const modifiedCount = container.querySelector('#modified-count');

  // ダミーデータ（実際はAPIから取得）
  const mockVersions = {
    contract: {
      v1: {
        title: '契約書 v1.0',
        date: '2024-01-15',
