      }
    }
  };

  // 差分計算関数
  function calculateDiff(text1, text2) {
    const lines1 = text1.split('\n');
    const lines2 = text2.split('\n');
    const changes = [];
    const maxLen = Math.max(lines1.length, lines2.length);

    for (let i = 0; i < maxLen; i++) {
      const line1 = lines1[i] || '';
      const line2 = lines2[i] || '';

      if (line1 !== line2) {
        if (!line1 && line2) {
          changes.push({ type: 'added', line: line2, index: i });
        } else if (line1 && !line2) {
          changes.push({ type: 'deleted', line: line1, index: i });
        } else {
          changes.push({ type: 'modified', before: line1, after: line2, index: i });
        }
      }
    }
    return changes;
  }

  // ハイライト付きテキスト生成
  function renderWithHighlight(text, changes, isV2 = false) {
    const lines = text.split('\n');
    const changeMap = {};

    changes.forEach(change => {
      if (isV2 && (change.type === 'added' || change.type === 'modified')) {
        changeMap[change.index] = change.type;
      } else if (!isV2 && (change.type === 'deleted' || change.type === 'modified')) {
        changeMap[change.index] = change.type;
      }
    });

    return lines.map((line, idx) => {
      const changeType = changeMap[idx];
      if (!changeType) return line;

      let bgColor = '';
      if (changeType === 'added') bgColor = 'rgba(74, 222, 128, 0.15)';
      else if (changeType === 'deleted') bgColor = 'rgba(239, 68, 68, 0.15)';
      else if (changeType === 'modified') bgColor = 'rgba(234, 179, 8, 0.15)';

      return `<span style="background: ${bgColor}; display: block; padding: 2px 4px; margin: 0 -4px;">${line}</span>`;
    }).join('\n');
  }

  // 比較実行
  compareBtn.addEventListener('click', async () => {
    const docType = docSelect.value;
    const v1Key = v1Select.value;
    const v2Key = v2Select.value;

    if (!docType || !v1Key || !v2Key) {
      alert('ドキュメント、バージョン1、バージョン2を選択してください');
      return;
    }

    if (v1Key === v2Key) {
      alert('異なるバージョンを選択してください');
      return;
    }

    const v1Data = mockVersions[docType][v1Key];
    const v2Data = mockVersions[docType][v2Key];

    // 差分計算
    const changes = calculateDiff(v1Data.content, v2Data.content);
    const added = changes.filter(c => c.type === 'added').length;
    const deleted = changes.filter(c => c.type === 'deleted').length;
    const modified = changes.filter(c => c.type === 'modified').length;

    // サマリー更新
    addedCount.textContent = added;
    deletedCount.textContent = deleted;
    modifiedCount.textContent = modified;

    // パネル更新
    v1Info.textContent = `(${v1Data.date} / ${v1Data.creator})`;
    v2Info.textContent = `(${v2Data.date} / ${v2Data.creator})`;

    v1Panel.innerHTML = renderWithHighlight(v1Data.content, changes, false);
    v2Panel.innerHTML = renderWithHighlight(v2Data.content, changes, true);

    // 変更詳細テーブル
    changeDetailsTbody.innerHTML = changes.map(change => {
      let typeLabel = '';
      let typeColor = '';
      if (change.type === 'added') {
        typeLabel = '追加';
        typeColor = '#4ade80';
      } else if (change.type === 'deleted') {
        typeLabel = '削除';
        typeColor = '#ef4444';
      } else if (change.type === 'modified') {
        typeLabel = '変更';
        typeColor = '#eab308';
      }

      const beforeText = change.before || change.line || '';
      const afterText = change.after || change.line || '';

      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 6px 8px; color: ${typeColor}; font-weight: 600;">${typeLabel}</td>
          <td style="padding: 6px 8px; color: var(--text-muted);">行 ${change.index + 1}</td>
          <td style="padding: 6px 8px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${beforeText.substring(0, 30)}</td>
          <td style="padding: 6px 8px; color: var(--text); max-width: 200px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${afterText.substring(0, 30)}</td>
        </tr>
      `;
    }).join('');

    // UI表示
    changeSummary.style.display = 'grid';
    comparisonPanels.style.display = 'flex';
    changeDetailsSection.style.display = 'flex';
    exportSection.style.display = 'flex';
  });

  // エクスポート
  exportBtn.addEventListener('click', () => {
    const docType = docSelect.value;
    const v1Key = v1Select.value;
    const v2Key = v2Select.value;

    const v1Data = mockVersions[docType][v1Key];
    const v2Data = mockVersions[docType][v2Key];
    const changes = calculateDiff(v1Data.content, v2Data.content);

    let csv = '\uFEFF種別,フィールド,変更前,変更後\n';
    changes.forEach(change => {
      let type = '';
      if (change.type === 'added') type = '追加';
      else if (change.type === 'deleted') type = '削除';
      else if (change.type === 'modified') type = '変更';

      const before = (change.before || change.line || '').replace(/"/g, '""');
      const after = (change.after || change.line || '').replace(/"/g, '""');

      csv += `${type},"行 ${change.index + 1}","${before}","${after}"\n`;
    });

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `comparison_${docType}_${v1Key}_vs_${v2Key}.csv`;
    link.click();
  });

  // 戻るボタン
  backBtn.addEventListener('click', () => {
    window.showScreen('scr-1782112376817');
  });
}

function(container, apiUrl, tables) {
  const docTypeSelect = container.querySelector('[data-testid="document-type-select"]');
  const documentList = container.querySelector('#document-list');
  const currentDocPanel = container.querySelector('#current-doc-panel');
  const currentDocName = container.querySelector('#current-doc-name');
  const currentVersionNum = container.querySelector('#current-version-num');
  const currentUpdateDate = container.querySelector('#current-update-date');
  const currentStatus = container.querySelector('#current-status');
  const changeUserName = container.querySelector('#change-user-name');
  const newVersionNumberInput = container.querySelector('[data-testid="new-version-number"]');
  const changeDatetimeInput = container.querySelector('[data-testid="change-datetime"]');
  const versionTitleInput = container.querySelector('[data-testid="version-title"]');
  const changeDescriptionInput = container.querySelector('[data-testid="change-description"]');
  const fileDropZone = container.querySelector('#file-drop-zone');
  const fileInput = container.querySelector('[data-testid="file-input"]');
  const fileName = container.querySelector('#file-name');
  const saveButton = container.querySelector('[data-testid="save-button"]');
  const cancelButton = container.querySelector('[data-testid="cancel-button"]');
  const compareButton = container.querySelector('[data-testid="compare-versions-btn"]');
  const compareModal = container.querySelector('#compare-modal');
  const closeCompareModal = container.querySelector('#close-compare-modal');
  const closeCompareBtn = container.querySelector('#close-compare-btn');
  const changeHistoryPreview = container.querySelector('#change-history-preview');
  const historyList = container.querySelector('#history-list');

  let selectedDocument = null;
  let selectedDocumentType = null;
  let uploadedFile = null;
  let currentUser = null;

  // 現在のユーザー情報取得
  async function loadCurrentUser() {
    const users = await window.aivicApi.list(5); // ユーザーテーブル
    if (users && users.length > 0) {
      currentUser = users[0]; // 簡略化：最初のユーザーを現在ユーザーとする
      changeUserName.textContent = currentUser.氏名 || currentUser.ユーザー名 || '-';
    }
  }

  // 資料一覧を再読み込み
  async function loadDocuments() {
    documentList.innerHTML = '';
    const docType = docTypeSelect.value;

    let documents = [];
    let tableIndex = -1;

    if (docType === 'contract' || docType === '') {
      const contracts = await window.aivicApi.list(0); // 契約書テーブル
      if (contracts) {
        documents.push(...contracts.map(c => ({ ...c, type: 'contract', id: c.契約書ID, name: c.契約書名 })));
      }
    }

    if (docType === 'proposal' || docType === '') {
      const proposals = await window.aivicApi.list(1); // 提案資料テーブル
      if (proposals) {
        documents.push(...proposals.map(p => ({ ...p, type: 'proposal', id: p.提案資料ID, name: p.提案資料名 })));
      }
    }

    documents.forEach(doc => {
      const item = document.createElement('div');
      item.style.cssText = 'padding: 10px; border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s; font-size: 12px;';
      item.innerHTML = `
        <div style="font-weight: 500; color: var(--text); margin-bottom: 2px;">${doc.name}</div>
        <div style="font-size: 11px; color: var(--text-muted);">${doc.type === 'contract' ? '契約書' : '提案資料'}</div>
      `;
      item.addEventListener('click', () => selectDocument(doc));
      item.addEventListener('mouseover', () => item.style.background = 'rgba(255,255,255,0.08)');
      item.addEventListener('mouseout', () => item.style.background = 'transparent');
      documentList.appendChild(item);
    });
  }

  // 資料を選択
  async function selectDocument(doc) {
    selectedDocument = doc;
    selectedDocumentType = doc.type;
    currentDocPanel.style.display = 'block';

    currentDocName.textContent = doc.name;
    currentStatus.textContent = doc.ステータス || '-';

    // 現在バージョン情報を取得
    let versions = [];
    if (doc.type === 'contract') {
      versions = await window.aivicApi.list(2); // 契約書バージョン
      versions = versions.filter(v => v.契約書ID === doc.id);
    } else {
      versions = await window.aivicApi.list(3); // 提案資料バージョン
      versions = versions.filter(v => v.提案資料ID === doc.id);
    }

    if (versions.length > 0) {
      const latestVersion = versions.sort((a, b) => (b.バージョン番号 || 0) - (a.バージョン番号 || 0))[0];
      currentVersionNum.textContent = latestVersion.バージョン番号 || '-';
      currentUpdateDate.textContent = latestVersion.作成日時 ? new Date(latestVersion.作成日時).toLocaleString('ja-JP') : '-';
      newVersionNumberInput.value = (latestVersion.バージョン番号 || 0) + 1;
    } else {
      currentVersionNum.textContent = '-';
      currentUpdateDate.textContent = '-';
      newVersionNumberInput.value = 1;
    }

    // 変更日時を現在時刻に設定
    const now = new Date();
    const isoString = now.toISOString().slice(0, 16);
    changeDatetimeInput.value = isoString;

    // 変更履歴を表示
    loadChangeHistory(doc.id, doc.type);

    // フォームをリセット
    versionTitleInput.value = '';
    changeDescriptionInput.value = '';
    fileName.textContent = '';
    uploadedFile = null;
  }

  // 変更履歴を読み込み
  async function loadChangeHistory(docId, docType) {
    const histories = await window.aivicApi.list(4); // 変更履歴テーブル
    const filtered = histories.filter(h => h.対象ID === docId && h.対象テーブル === (docType === 'contract' ? '契約書' : '提案資料'));

    if (filtered.length > 0) {
      changeHistoryPreview.style.display = 'block';
      historyList.innerHTML = filtered.slice(0, 5).map(h => `
        <div style="margin-bottom: 6px; padding-bottom: 6px; border-bottom: 1px solid rgba(255,255,255,0.08);">
          <div style="font-weight: 500;">${h.変更種別}</div>
          <div style="font-size: 11px; color: var(--text-muted);">${new Date(h.作成日時).toLocaleString('ja-JP')}</div>
        </div>
      `).join('');
    } else {
      changeHistoryPreview.style.display = 'none';
    }
  }

  // ファイルアップロード処理
  fileDropZone.addEventListener('click', () => fileInput.click());
  fileDropZone.addEventListener('dragover', (e) => {
    e.preventDefault();
    fileDropZone.style.background = 'rgba(255,255,255,0.15)';
    fileDropZone.style.borderColor = 'var(--primary)';
  });
  fileDropZone.addEventListener('dragleave', () => {
    fileDropZone.style.background = 'rgba(0,0,0,0.1)';
    fileDropZone.style.borderColor = 'rgba(255,255,255,0.3)';
  });
  fileDropZone.addEventListener('drop', (e) => {
    e.preventDefault();
    fileDropZone.style.background = 'rgba(0,0,0,0.1)';
    fileDropZone.style.borderColor = 'rgba(255,255,255,0.3)';
    if (e.dataTransfer.files.length > 0) {
      uploadedFile = e.dataTransfer.files[0];
      fileName.textContent = `✓ ${uploadedFile.name}`;
    }
  });
  fileInput.addEventListener('change', (e) => {
    if (e.target.files.length > 0) {
      uploadedFile = e.target.files[0];
      fileName.textContent = `✓ ${uploadedFile.name}`;
    }
  });

  // 比較モーダル
  compareButton.addEventListener('click', async () => {
    if (!selectedDocument) return;

    let versions = [];
    if (selectedDocumentType === 'contract') {
      versions = await window.aivicApi.list(2);
      versions = versions.filter(v => v.契約書ID === selectedDocument.id);
    } else {
      versions = await window.aivicApi.list(3);
      versions = versions.filter(v => v.提案資料ID === selectedDocument.id);
    }

    const prevVersion = versions.length > 0 ? versions.sort((a, b) => (b.バージョン番号 || 0) - (a.バージョン番号 || 0))[0] : null;
    container.querySelector('#prev-version-content').textContent = prevVersion ? (prevVersion.変更内容 || prevVersion.内容 || '-') : '前バージョンなし';
    container.querySelector('#new-version-content').textContent = changeDescriptionInput.value || '（未入力）';

    compareModal.style.display = 'flex';
  });

  closeCompareModal.addEventListener('click', () => compareModal.style.display = 'none');
  closeCompareBtn.addEventListener('click', () => compareModal.style.display = 'none');

  // 保存処理
  saveButton.addEventListener('click', async () => {
    if (!selectedDocument) {
      alert('資料を選択してください');
      return;
    }

    const versionNumber = parseInt(newVersionNumberInput.value) || 1;
    const versionTitle = versionTitleInput.value.trim();
    const changeDescription = changeDescriptionInput.value.trim();
    const changeDateTime = changeDatetimeInput.value;

    if (!versionTitle || !changeDescription) {
      alert('バージョン名称と変更内容説明を入力してください');
      return;
    }

    // バージョン情報を保存
    const versionData = {
      バージョン番号: versionNumber,
      タイトル: versionTitle,
      内容: changeDescription,
      変更内容: changeDescription,
      ステータス: '下書き',
      作成者ID: currentUser?.ユーザーID || 'unknown',
      作成日時: new Date(changeDateTime).toISOString(),
      ファイルパス: uploadedFile ? `/uploads/${uploadedFile.name}` : null,
    };

    if (selectedDocumentType === 'contract') {
      versionData.契約書ID = selectedDocument.id;
      await window.aivicApi.save(2, versionData); // 契約書バージョン保存
    } else {
      versionData.提案資料ID = selectedDocument.id;
      await window.aivicApi.save(3, versionData); // 提案資料バージョン保存
    }

    // 変更履歴を記録
    const historyData = {
      対象テーブル: selectedDocumentType === 'contract' ? '契約書' : '提案資料',
      対象ID: selectedDocument.id,
      変更種別: 'バージョン作成',
      変更フィールド: 'バージョン',
      変更前値: (currentVersionNum.textContent || '-'),
      変更後値: versionNumber.toString(),
      変更理由: changeDescription,
      作成者ID: currentUser?.ユーザーID || 'unknown',
      作成日時: new Date().toISOString(),
    };
    await window.aivicApi.save(4, historyData);

    alert('バージョン情報を保存しました');
    versionTitleInput.value = '';
    changeDescriptionInput.value = '';
    fileName.textContent = '';
    uploadedFile = null;
    loadDocuments();
  });

  // キャンセル
  cancelButton.addEventListener('click', () => {
    versionTitleInput.value = '';
    changeDescriptionInput.value = '';
    fileName.textContent = '';
    uploadedFile = null;
    selectedDocument = null;
    currentDocPanel.style.display = 'none';
  });

  // 資料種別フィルタ変更
  docTypeSelect.addEventListener('change', loadDocuments);

  // 初期化
  loadCurrentUser();
  loadDocuments();
}

