  const CHANGE_LOG_IDX = tables.findIndex(t => t.tableName === '変更履歴');

  // 状態管理
  let currentDocType = null;
  let currentDocId = null;
  let versions = [];
  let selectedVersionId = null;
  let selectedArchiveVersionIds = new Set();

  // DOM 要素
  const docSelect = container.querySelector('#document-select');
  const docTypeFilter = container.querySelector('#doc-type-filter');
  const versionTbody = container.querySelector('#version-tbody');
  const selectAllCheckbox = container.querySelector('#select-all-versions');
  const setLatestBtn = container.querySelector('#set-latest-btn');
  const archiveBtn = container.querySelector('#archive-btn');
  const archiveReasonInput = container.querySelector('#archive-reason');
  const latestVersionPanel = container.querySelector('#latest-version-panel');
  const selectedVersionInfo = container.querySelector('#selected-version-info');
  const archiveSelectedList = container.querySelector('#archive-selected-list');
  const successMsg = container.querySelector('#success-message');
  const errorMsg = container.querySelector('#error-message');

  // ユーティリティ
  function showMessage(type, text) {
    const el = type === 'success' ? successMsg : errorMsg;
    el.textContent = text;
    el.style.display = 'block';
    setTimeout(() => { el.style.display = 'none'; }, 3000);
  }

  function formatDate(timestamp) {
    if (!timestamp) return '-';
    const d = new Date(timestamp);
    return d.toLocaleDateString('ja-JP') + ' ' + d.toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  }

  function getLatestVersionId(versionList) {
    return versionList.find(v => v.latest_flag === true || v.latest_flag === 1)?.id;
  }

  // 文書一覧を取得して select に追加
  async function loadDocuments() {
    try {
      const contracts = CONTRACT_IDX >= 0 ? await window.aivicApi.list(CONTRACT_IDX) : [];
      const proposals = PROPOSAL_IDX >= 0 ? await window.aivicApi.list(PROPOSAL_IDX) : [];

      // select をリセット
      docSelect.innerHTML = '<option value="">選択してください</option>';

      if (contracts && contracts.length > 0) {
        contracts.forEach(c => {
          const opt = document.createElement('option');
          opt.value = `contract:${c.id}`;
          opt.textContent = `[契約書] ${c.contract_name || c.name || 'Untitled'}`;
          docSelect.appendChild(opt);
        });
      }

      if (proposals && proposals.length > 0) {
        proposals.forEach(p => {
          const opt = document.createElement('option');
          opt.value = `proposal:${p.id}`;
          opt.textContent = `[提案資料] ${p.proposal_name || p.name || 'Untitled'}`;
          docSelect.appendChild(opt);
        });
      }
    } catch (err) {
      console.error('Failed to load documents:', err);
    }
  }

  // バージョン一覧を読み込み
  async function loadVersions() {
    if (!currentDocType || !currentDocId) {
      versionTbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="6" style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">文書を選択してください</td></tr>';
      return;
    }

    try {
      const tableIdx = currentDocType === 'contract' ? CONTRACT_VERSION_IDX : PROPOSAL_VERSION_IDX;
      if (tableIdx < 0) {
        versionTbody.innerHTML = '<tr><td colspan="6" style="padding: 16px; text-align: center; color: var(--text-muted);">バージョンテーブルが見つかりません</td></tr>';
        return;
      }

      const allVersions = await window.aivicApi.list(tableIdx);
      versions = allVersions.filter(v => 
        (currentDocType === 'contract' ? v.contract_id : v.proposal_id) === currentDocId
      ).sort((a, b) => (b.version_number || 0) - (a.version_number || 0));

      renderVersionTable();
      resetSelection();
    } catch (err) {
      console.error('Failed to load versions:', err);
      showMessage('error', 'バージョン読み込みエラー');
    }
  }

  // バージョンテーブルを描画
  function renderVersionTable() {
    if (versions.length === 0) {
      versionTbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(255,255,255,0.05);"><td colspan="6" style="padding: 16px; text-align: center; color: var(--text-muted); font-size: 12px;">バージョンがありません</td></tr>';
      return;
    }

    versionTbody.innerHTML = versions.map(v => {
      const isLatest = v.latest_flag === true || v.latest_flag === 1;
      const isArchived = v.status === 'archived' || v.status === 'アーカイブ';
      return `
        <tr 
          data-id="${v.id}" 
          style="border-bottom: 1px solid rgba(255,255,255,0.05); cursor: pointer; background: ${isArchived ? 'rgba(0,0,0,0.15)' : 'transparent'};"
          class="version-row"
        >
          <td style="padding: 6px 8px;">
            <input 
              type="checkbox" 
              class="version-checkbox" 
              data-version-id="${v.id}"
              data-version-num="${v.version_number}"
              style="accent-color: var(--primary);"
              ${isLatest ? 'disabled' : ''}
            />
          </td>
          <td style="padding: 6px 8px; color: var(--text); font-weight: 500;">v${v.version_number || 1}</td>
          <td style="padding: 6px 8px; color: var(--text-muted); font-size: 11px;">${formatDate(v.created_at)}</td>
          <td style="padding: 6px 8px; color: var(--text-muted); font-size: 11px;">${v.creator_name || v.created_by || '-'}</td>
          <td style="padding: 6px 8px;">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 10px; font-weight: 600; background: ${
              v.status === 'approved' || v.status === '承認済み' ? 'rgba(76,175,80,0.2); color: #4caf50;' :
              v.status === 'review' || v.status === 'レビュー中' ? 'rgba(255,193,7,0.2); color: #ffc107;' :
              v.status === 'archived' || v.status === 'アーカイブ' ? 'rgba(158,158,158,0.2); color: #9e9e9e;' :
              'rgba(33,150,243,0.2); color: #2196f3;'
            }">
              ${v.status || 'draft'}
            </span>
          </td>
          <td style="padding: 6px 8px; text-align: center;">
            ${isLatest ? '<span style="color: #d4af37; font-weight: 700; font-size: 14px;">★</span>' : '-'}
          </td>
        </tr>
      `;
    }).join('');

    // イベントリスナー
    container.querySelectorAll('.version-row').forEach(row => {
      row.addEventListener('click', (e) => {
        if (e.target.tagName !== 'INPUT') {
          selectVersionForLatest(row.dataset.id);
        }
      });
    });

    container.querySelectorAll('.version-checkbox').forEach(cb => {
      cb.addEventListener('change', (e) => {
        const versionId = e.target.dataset.versionId;
        if (e.target.checked) {
          selectedArchiveVersionIds.add(versionId);
        } else {
          selectedArchiveVersionIds.delete(versionId);
        }
        updateArchiveUI();
      });
    });

    selectAllCheckbox.checked = false;
  }

  // 最新版設定用にバージョンを選択
  function selectVersionForLatest(versionId) {
    selectedVersionId = versionId;
    const v = versions.find(x => x.id === versionId);
    if (v) {
      selectedVersionInfo.textContent = `v${v.version_number} (${formatDate(v.created_at)})`;
      setLatestBtn.style.opacity = '1';
      setLatestBtn.style.pointerEvents = 'auto';
      setLatestBtn.disabled = false;
    }
  }

  // 最新版に設定
  async function setAsLatest() {
    if (!selectedVersionId || !currentDocType) return;

    try {
      const tableIdx = currentDocType === 'contract' ? CONTRACT_VERSION_IDX : PROPOSAL_VERSION_IDX;

      // 現在の最新版を取得
      const allVersions = await window.aivicApi.list(tableIdx);
      const currentLatest = allVersions.find(v => 
        (currentDocType === 'contract' ? v.contract_id : v.proposal_id) === currentDocId &&
        (v.latest_flag === true || v.latest_flag === 1)
      );

      // 現在の最新版フラグを解除
      if (currentLatest && currentLatest.id !== selectedVersionId) {
        await window.aivicApi.update(tableIdx, currentLatest.id, { latest_flag: false });
      }

      // 新しい最新版フラグを設定
      await window.aivicApi.update(tableIdx, selectedVersionId, { latest_flag: true });

      // 変更履歴を記録
      if (CHANGE_LOG_IDX >= 0) {
        await window.aivicApi.save(CHANGE_LOG_IDX, {
          target_table: currentDocType === 'contract' ? '契約書バージョン' : '提案資料バージョン',
          target_id: selectedVersionId,
          change_type: 'ステータス変更',
          change_field: 'latest_flag',
          change_before: currentLatest ? 'true' : 'false',
          change_after: 'true',
          change_reason: '最新版に設定',
          creator_id: 'current_user',
          created_at: new Date().toISOString()
        });
      }

      showMessage('success', '最新版を設定しました');
      await loadVersions();
    } catch (err) {
      console.error('Failed to set latest:', err);
      showMessage('error', '最新版設定に失敗しました');
    }
  }

  // アーカイブ処理
  async function archiveVersions() {
    if (selectedArchiveVersionIds.size === 0) {
      showMessage('error', 'アーカイブ対象を選択してください');
      return;
    }

    const reason = archiveReasonInput.value.trim();
    if (!reason) {
      showMessage('error', 'アーカイブ理由を入力してください');
      return;
    }

    try {
      const tableIdx = currentDocType === 'contract' ? CONTRACT_VERSION_IDX : PROPOSAL_VERSION_IDX;

      for (const versionId of selectedArchiveVersionIds) {
        await window.aivicApi.update(tableIdx, versionId, { 
          status: 'archived',
          updated_at: new Date().toISOString()
        });

        // 変更履歴を記録
        if (CHANGE_LOG_IDX >= 0) {
          await window.aivicApi.save(CHANGE_LOG_IDX, {
            target_table: currentDocType === 'contract' ? '契約書バージョン' : '提案資料バージョン',
            target_id: versionId,
            change_type: 'ステータス変更',
            change_field: 'status',
            change_before: 'active',
            change_after: 'archived',
            change_reason: reason,
            creator_id: 'current_user',
            created_at: new Date().toISOString()
          });
        }
      }

      showMessage('success', `${selectedArchiveVersionIds.size}件のバージョンをアーカイブしました`);
      await loadVersions();
    } catch (err) {
      console.error('Failed to archive:', err);
      showMessage('error', 'アーカイブ処理に失敗しました');
    }
  }

  // UI 更新
  function updateArchiveUI() {
    const selectedCount = selectedArchiveVersionIds.size;
    if (selectedCount === 0) {
      archiveSelectedList.innerHTML = '<div style="text-align: center; padding: 12px; color: var(--text-muted); font-size: 11px;">選択なし</div>';
      archiveBtn.style.opacity = '0.5';
      archiveBtn.style.pointerEvents = 'none';
      archiveBtn.disabled = true;
    } else {
      const selectedVersions = versions.filter(v => selectedArchiveVersionIds.has(v.id));
      archiveSelectedList.innerHTML = selectedVersions.map(v => 
        `<div style="padding: 4px 0; font-size: 11px; color: var(--text);">v${v.version_number}</div>`
      ).join('');
      archiveBtn.style.opacity = '1';
      archiveBtn.style.pointerEvents = 'auto';
      archiveBtn.disabled = false;
    }
  }

  function resetSelection() {
    selectedVersionId = null;
    selectedArchiveVersionIds.clear();
    selectAllCheckbox.checked = false;
    selectedVersionInfo.textContent = '未選択';
    setLatestBtn.style.opacity = '0.5';
    setLatestBtn.style.pointerEvents = 'none';
    setLatestBtn.disabled = true;
    archiveReasonInput.value = '';
    updateArchiveUI();
  }

  // イベントリスナー
  docSelect.addEventListener('change', (e) => {
    const [type, id] = e.target.value.split(':');
    currentDocType = type || null;
    currentDocId = id || null;
    loadVersions();
  });

  docTypeFilter.addEventListener('change', () => {
    // フィルタ機能（オプション）
  });

  selectAllCheckbox.addEventListener('change', (e) => {
    container.querySelectorAll('.version-checkbox:not(:disabled)').forEach(cb => {
      cb.checked = e.target.checked;
      const versionId = cb.dataset.versionId;
      if (e.target.checked) {
        selectedArchiveVersionIds.add(versionId);
      } else {
        selectedArchiveVersionIds.delete(versionId);
      }
    });
    updateArchiveUI();
  });

  setLatestBtn.addEventListener('click', setAsLatest);
  archiveBtn.addEventListener('click', archiveVersions);

  // 初期化
  loadDocuments();
}
